<?php require_once __DIR__.'/includes/functions.php';if(me())go(role_home());$err='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['nama_lengkap']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$err='Isi nama, email valid, dan kata sandi minimal 8 karakter.';else{try{$phone=trim($_POST['no_hp']??'');$address=trim($_POST['alamat']??'');$s=db()->prepare("INSERT INTO users(nama_lengkap,email,password,no_hp,alamat,role) VALUES(?,?,?,?,?,'masyarakat')");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$phone,$address]);flash('success','Registrasi berhasil. Silakan masuk.');go('login.php');}catch(PDOException $e){$err='Email sudah digunakan atau data tidak dapat disimpan.';}}}header_page('Daftar');?><section class="auth card"><h1>Daftar masyarakat</h1><?php if($err):?><div class="alert error"><?=e($err)?></div><?php endif;?><form method="post"><?=csrf_input()?><label>Nama lengkap<input name="nama_lengkap" required maxlength="120"></label><label>Email<input type="email" name="email" required></label><label>Nomor HP (opsional)<input name="no_hp" maxlength="30"></label><label>Alamat (opsional)<textarea name="alamat"></textarea></label><label>Kata sandi<input type="password" name="password" minlength="8" required></label><button class="btn">Buat akun</button></form><p>Sudah punya akun? <a href="login.php">Masuk</a></p></section><?php footer_page();?>